.reaction--css {
  bottom: 0;
  left: var(--x);
  font-size: var(--size-start);
  animation:
    rise var(--life) ease-out forwards,
    sway var(--sway-period) ease-in-out var(--sway-delay) infinite alternate;
}

@keyframes rise {
  0% {
    bottom: 0;
    font-size: var(--size-start);
